# Banking keeps the questions every department was given a copy of in 0014.
KEEPS_QUESTIONS = "banking"
# Stages after which an application needs nothing more from its questions.
DECIDED = ("ACCEPTED", "REJECTED")


def _free_label(Version, start: int) -> str:
    n = start
    while Version.objects.filter(label=f"v{n}").exists():
        n += 1
    return f"v{n}"


def empty_other_departments(apps, schema_editor):
    """Banking keeps today's questions; every other department starts with none, to have its own
    set up by its admins. A department with an application not decided yet keeps its questions
    (none is lost mid-application), and is named here. Each department remembers the edition it
    started from, for "Restore published model"."""
    Department = apps.get_model("cases", "Department")
    Version = apps.get_model("cases", "QuestionnaireVersion")
    Assessment = apps.get_model("cases", "Assessment")
    published = Version.objects.filter(department__isnull=True).order_by("pk").first()
    for department in Department.objects.order_by("pk"):
        in_progress = Assessment.objects.filter(department=department).exclude(stage__in=DECIDED).exists()
        if department.key == KEEPS_QUESTIONS or in_progress:
            if department.key != KEEPS_QUESTIONS:
                print(f"\n  {department.name} keeps its questions: it has an application in progress.")
            department.starting_version = published
            department.save(update_fields=["starting_version"])
            continue
        Version.objects.filter(department=department, is_active=True).update(is_active=False)
        top = Version.objects.aggregate(n=models.Max("pk"))["n"] or 0
        empty = Version.objects.create(label=_free_label(Version, top + 1), is_active=True, department=department)
        department.starting_version = empty
        department.save(update_fields=["starting_version"])
    schema_editor.execute("SET CONSTRAINTS ALL IMMEDIATE")


def restore_copies(apps, schema_editor):
    """Back: each emptied department takes up again the copy it had before (its latest edition
    with questions)."""
    Department = apps.get_model("cases", "Department")
    Version = apps.get_model("cases", "QuestionnaireVersion")
    for department in Department.objects.all():
        active = Version.objects.filter(department=department, is_active=True).first()
        if active is not None and not active.questions.exists():
            before = (
                Version.objects.filter(department=department, questions__isnull=False)
                .order_by("-pk").distinct().first()
            )
            if before is not None:
                Version.objects.filter(pk=active.pk).update(is_active=False)
                Version.objects.filter(pk=before.pk).update(is_active=True)
    Department.objects.update(starting_version=None)
    schema_editor.execute("SET CONSTRAINTS ALL IMMEDIATE")


